CREATE TABLE IF NOT EXISTS `bow_setups` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `brand` TEXT NOT NULL, `model` TEXT NOT NULL, `drawWeightLbs` TEXT NOT NULL, `drawLengthIn` TEXT NOT NULL, `rest` TEXT NOT NULL, `sight` TEXT NOT NULL, `arrows` TEXT NOT NULL, `notes` TEXT NOT NULL, `limbShiftSetting` TEXT NOT NULL, `yokeTwistNotes` TEXT NOT NULL, `camSystem` TEXT NOT NULL, `nextTuneDueEpochMs` INTEGER, `iboSpeedFps` TEXT NOT NULL, `arrowSpeedFps` TEXT NOT NULL, `lastCamCheckEpochMs` INTEGER, `camTimingNotes` TEXT NOT NULL, `lastCableCheckEpochMs` INTEGER, `cableStretchNotes` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `tune_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `dateEpochMs` INTEGER NOT NULL, `distanceYd` TEXT NOT NULL, `scoreOrGroup` TEXT NOT NULL, `notes` TEXT NOT NULL, `setupName` TEXT NOT NULL, `sessionKind` TEXT NOT NULL, `indoorOutdoor` TEXT NOT NULL, `windNote` TEXT NOT NULL, `tempNote` TEXT NOT NULL, `tearType` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `guided_tune_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `protocolId` TEXT NOT NULL, `title` TEXT NOT NULL, `setupName` TEXT NOT NULL, `startedAtEpochMs` INTEGER NOT NULL, `updatedAtEpochMs` INTEGER NOT NULL, `completedAtEpochMs` INTEGER, `currentBlockIndex` INTEGER NOT NULL, `blockLogsJson` TEXT NOT NULL, `status` TEXT NOT NULL, `bareShaftHl20` TEXT NOT NULL, `bareShaftLr20` TEXT NOT NULL, `walkBackLr30` TEXT NOT NULL, `final30GroupSize` TEXT NOT NULL, `decisionNotes` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `arrow_shafts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `setupId` INTEGER, `name` TEXT NOT NULL, `brand` TEXT NOT NULL, `spine` TEXT NOT NULL, `lengthIn` TEXT NOT NULL, `gpi` TEXT NOT NULL, `pointWeightGr` TEXT NOT NULL, `insertWeightGr` TEXT NOT NULL, `nockWeightGr` TEXT NOT NULL, `vaneWeightGr` TEXT NOT NULL, `wrapWeightGr` TEXT NOT NULL, `balanceFromNockIn` TEXT NOT NULL, `quantity` TEXT NOT NULL, `notes` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `paper_tear_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `dateEpochMs` INTEGER NOT NULL, `tearType` TEXT NOT NULL, `setupName` TEXT NOT NULL, `distanceFt` TEXT NOT NULL, `notes` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `adjustment_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `dateEpochMs` INTEGER NOT NULL, `setupName` TEXT NOT NULL, `kind` TEXT NOT NULL, `beforeValue` TEXT NOT NULL, `afterValue` TEXT NOT NULL, `notes` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `maintenance_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `setupName` TEXT NOT NULL, `kind` TEXT NOT NULL, `dateEpochMs` INTEGER NOT NULL, `notes` TEXT NOT NULL, `nextDueEpochMs` INTEGER);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
